@st.cache_resource
def get_cities():
  un_city=df['City'].unique()
  print('percentage of missing entries:')
  for city in un_city:
    cdf=df[df['City']==city]
    total=len(cdf)
    aqi_missing_percentage = cdf['AQI'].isnull().sum()/total*100
    print(f'{city.upper():<12} \ttotal:{total}\tMissing:{aqi_missing_percentage:.2f}%')

  cities=[city for city in un_city if len(df[df['City']==city])>1600]
  cities.remove('Mumbai')
  cities.remove('Ahmedabad')
  return cities
cities=get_cities()
print('\nSelected Cities',cities)

# """Among all cities having total number of rows greater than 1600 we dropped Mumbai and Ahmedabad from cities list as the percentages of missing AQI entries int these subsets of dataframe are 61.42 and 33.60% respectively

# ###Time series Interpolation
# to fill missing values in arima and prophet we should use time series interpolation
# <br><br>
# Linear Interpolation estimates missing values by drawing a straight line between the two closest known data points in time
# """

@st.cache_resource
def get_separate_df():
  df_list={}
  for city in cities:
    curr_df=df[df['City']==city].copy()
    curr_df.set_index('Date',inplace=True)
    full_range=pd.date_range(start=curr_df.index.min(),end=curr_df.index.max(),freq='D')
    curr_df = curr_df.reindex(full_range)

    numerical_cols = [col for col in curr_df.columns if curr_df[col].dtype == np.float64 and col != 'AQI_Bucket']
    for col in numerical_cols:
      curr_df[col] = curr_df[col].interpolate(method='linear')
      curr_df[col] = curr_df[col].clip(lower=0)

    curr_df['AQI_Bucket'] = curr_df['AQI_Bucket'].ffill().bfill()

    curr_df=curr_df.ffill().bfill()

  # Adding dataframe to the list of dataframe for different cities
    curr_df=curr_df.drop('City',axis=1)
    df_list[city]=curr_df
  return df_list
