# """### Feature Engineering for Time Series Models

# Now that the data is cleaned and interpolated, we'll create additional features that can help ARIMA and Prophet models capture patterns more effectively. These include:

# 1.  **Time-based Features**: Extracting components like year, month, day of week, etc., from the date index.

# """

# 1. Create Time-based Features
@st.cache_resource
def add_time_features():
  for city, curr_df in df_list.items():
    curr_df['Year'] = curr_df.index.year
    curr_df['Month'] = curr_df.index.month
    curr_df['Day'] = curr_df.index.day
    curr_df['DayOfWeek'] = curr_df.index.dayofweek # Monday=0, Sunday=6
    curr_df['DayOfYear'] = curr_df.index.dayofyear
    curr_df['WeekOfYear'] = curr_df.index.isocalendar().week.astype(int)
    curr_df['Quarter'] = curr_df.index.quarter
    df_list[city] = curr_df.copy() # Update the df_list with new features
    #removing empty columns
  for city in df_list:
    for col in df_list[city]:
      if df_list[city][col].isnull().sum()==len(df_list[city]):
        df_list[city]=df_list[city].drop(columns=[col])

  return df_list
df_list=add_time_features()
print("Time-based features added to each city's DataFrame.")

